261			}
262			rel = filepath.ToSlash(rel)
263	
264			var records []historyRecord
265			if cached, ok := prevCache.Files[rel]; ok && cached.Size == file.Size && cached.ModUnixNano == file.ModUnixNano {
266				records = cached.Records
267			} else {
268				scanned, scanErr := scanHistoryFile(outputDir, file.Path)
269				if scanErr != nil {
