			case reinforcementSuccess:
				counts.Success++
			case reinforcementCorrected:
				counts.Corrected++
			default:
				counts.Neutral++
			}
			ep := episodeRecord{
				ID:              episodeID(session.SessionID, i, turn.Text),
				RepoKey:         manifest.RepoKey,
				SessionID:       session.SessionID,
				CheckpointID:    session.LatestCheckpoint,
