	}
	return source, nil
}

// loadBrainEpisodes reads the persisted episode layer. Missing file -> empty.
func loadBrainEpisodes(brainDir string) ([]episodeRecord, error) {
	content, err := readBrainRelativeFile(brainDir, patternsEpisodesPath)
	if err != nil {
		return nil, nil
	}
