	in := []skillMemoryRecord{{PatternID: "P1", Status: skillStatusActive, SkillName: "verify-release",
		Installs: []skillInstall{{Agents: []string{"claude-code"}, Path: "~/.claude/skills/verify-release/SKILL.md", ContentSHA: "sha256:abc"}},
