// Then write to: filepath.Join(workspaceBrainDir, "patterns/workspace-patterns.ndjson") or similar
```

---

## 5. Existing Workspace Command Structure: The Full Pattern

**Key loop from workspace regressions** (lines 1322-1347):

```go
func runWorkspaceRegressions(cmd *cobra.Command, opts Options, ro regressionDetectorOptions, workspaceName, query string) error {
	if ro.limit <= 0 {
		return errors.New("--limit must be greater than zero")
	}
	manifest, err := loadWorkspaceManifest(opts.Env, workspaceName)  // <- Step 1: Load workspace
	if err != nil {
		return err
	}
	var results []workspaceRegressionResult
	for _, repo := range manifest.Repos {  // <- Step 2: Iterate members
		freshness := workspaceRepoFreshnessForRepo(cmd.Context(), opts, repo)
		result := workspaceRegressionResult{RepoKey: repo.RepoKey, Name: repo.Name, Freshness: freshness}
		if workspaceFreshnessBlocksScan(freshness) {
			result.Error = "skipped (unsafe): " + freshness.Detail
		} else {
			repoPath, anomalies, warnings, scanErr := scanWorkspaceRepoRegressions(cmd.Context(), opts, repo, ro, query)  // <- Step 3: Process member
			result.RepoPath = repoPath
			result.Anomalies = anomalies
			result.Warnings = warnings
			result.Error = scanErr
			if warn := workspaceFreshnessWarning(freshness); warn != "" {
				result.Warnings = append([]string{warn}, result.Warnings...)
			}
		}
		results = append(results, result)
	}
	// <- Step 4: Aggregate & output
	// ... JSON or text output of all results
	return nil
}
```

**The `scanWorkspaceRepoRegressions` helper** (lines 1288-1320) shows member processing:
```go
func scanWorkspaceRepoRegressions(ctx context.Context, opts Options, repo workspaceRepo, ro regressionDetectorOptions, query string) (string, []regressionAnomaly, []string, string) {
	brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)  // <- Get member brain
	if err != nil {
		return "", nil, nil, err.Error()
	}
	if repo.LocalPathHint == "" {
		return "", nil, nil, "no local_path_hint (re-add the repo to record its working tree)"
	}
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, repo.LocalPathHint)  // <- Get member repo dir
	if err != nil {
		return "", nil, nil, err.Error()
	}
	if !local {
		return "", nil, nil, "local_path_hint unavailable"
	}
	// Semantic source is optional: a sessions-only brain (no export manifest) still scans.
	var semSource *semanticSourceManifest
	if source, srcErr := workspaceSemanticSource(brainDir); srcErr == nil {
		semSource = source
	}
	anomalies, _, warnings := detectRegressionAnomalies(brainDir, repoDir, semSource, query, ro.limit, ro.includeDeletions)  // <- Process with both dirs
	// ... post-process anomalies
	return repoDir, anomalies, warnings, ""
}
```

---

## Summary for Implementation

To add `workspace patterns` subcommands that mirror the regressions/review pattern:

1. **Register**: Create `newWorkspacePatternsCommand()` returning a group, add subcommands (e.g., `aggregate`, `export`), call `cmd.AddCommand(newWorkspacePatternsCommand(opts))` in `newWorkspaceCommand()`.

2. **Resolve workspace**: Call `loadWorkspaceManifest(opts.Env, workspaceName)` to get the manifest.

3. **Iterate members**: Loop `for _, repo := range manifest.Repos`.

4. **Get member brain**: Call `brainDirForKey(opts.Env, repo.RepoKey)` for each member.

5. **Read patterns**: From each member brain, read `filepath.Join(brainDir, "patterns/episodes.ndjson")` (parsed as NDJSON of `episodeRecord`).

6. **Write workspace patterns**: Store aggregated results in `filepath.Join(workspaceBrainDir, "patterns/<filename>")` after calling `workspaceDir(opts.Env, workspaceName)`.

7. **Freshness checks**: Use `workspaceRepoFreshnessForRepo()` and `workspaceFreshnessBlocksScan()` before scanning (like regressions does).

