14	// Task candidates (Pattern Consolidation, Phase 2 redo).
15	//
16	// A task candidate is a RECURRING USER INTENT — not a command shape. Command
17	// n-grams were the wrong unit (they only ever surface generic, already-known
18	// operations); the thing worth turning into a skill is a task the user keeps
19	// doing in this repo, for which the brain holds non-obvious knowledge. Candidates
20	// are deterministic and cheap to compute; turning one into an actual SKILL.md is
21	// the agent-synthesis step (skill_synthesis.go), which is also where the
22	// "does this encode anything a model doesn't already know?" gate lives.
23	
24	const patternsTasksPath = "patterns/tasks.ndjson"
25	
26	const (
27		taskMinSupport      = 3 // distinct episodes sharing the intent
28		taskMinWithCommands = 2 // episodes that actually ran commands (drops chatter)
29		taskTopCommands     = 6
30		taskSampleIntents   = 3
31	)
32	
33	// nonTaskLeadWords head conversational continuations/acknowledgements, not tasks.
34	// An intent signature starting with one of these clusters unrelated episodes that
35	// merely followed the same filler word ("yes", "keep going", "great now …"), so
36	// it is not a coherent task candidate.
37	var nonTaskLeadWords = map[string]bool{
38		"yes": true, "no": true, "ok": true, "okay": true, "sure": true, "yep": true,
39		"yeah": true, "great": true, "thanks": true, "thx": true, "keep": true,
40		"now": true, "also": true, "hmm": true, "wait": true, "actually": true,
41		"go": true, "nice": true, "perfect": true, "cool": true, "right": true,
42		"done": true, "continue": true, "please": true, "good": true,
43	}
44	
45	func nonTaskSignature(sig string) bool {
46		head := sig
47		if i := strings.IndexByte(sig, ':'); i >= 0 {
48			head = sig[:i]
49		}
50		return nonTaskLeadWords[head]
51	}
