53	type taskCandidate struct {
54		ID              string              `json:"id"`
55		RepoKey         string              `json:"repo_key,omitempty"`
56		IntentSignature string              `json:"intent_signature"`
57		Label           string              `json:"label"`
58		Support         int                 `json:"support"`
59		WithCommands    int                 `json:"with_commands"`
60		Reinforcement   reinforcementCounts `json:"reinforcement"`
61		Commands        []string            `json:"commands,omitempty"`
62		SampleIntents   []string            `json:"sample_intents,omitempty"`
63		Examples        []episodeAnchor     `json:"examples,omitempty"`
64		Strength        float64             `json:"strength"`
65		StrengthLabel   string              `json:"strength_label"`
66	}
67	
68	func taskCandidateID(repoKey, signature string) string {
69		sum := sha256.Sum256([]byte(repoKey + "\x00" + signature))
70		return "task:" + hex.EncodeToString(sum[:])
71	}
72	
73	// buildTaskCandidates clusters episodes by intent signature into recurring tasks.
74	func buildTaskCandidates(episodes []episodeRecord) []taskCandidate {
75		type agg struct {
76			signature    string
77			support      int
78			withCommands int
79			reinf        reinforcementCounts
80			cmdFreq      map[string]int
81			intents      []string
82			anchors      []episodeAnchor
83			repoKey      string
84		}
85		aggs := map[string]*agg{}
86		order := []string{}
87		for i := range episodes {
88			ep := &episodes[i]
89			sig := ep.IntentSignature
90			if sig == "" {
91				continue
92			}
93			a := aggs[sig]
94			if a == nil {
95				a = &agg{signature: sig, cmdFreq: map[string]int{}, repoKey: ep.RepoKey}
96				aggs[sig] = a
97				order = append(order, sig)
98			}
99			a.support++
100			if len(ep.CommandSequence) > 0 {
101				a.withCommands++
102			}
103			switch ep.Reinforcement {
104			case reinforcementSuccess:
105				a.reinf.Success++
106			case reinforcementCorrected:
107				a.reinf.Corrected++
108			default:
109				a.reinf.Neutral++
110			}
111			for _, c := range ep.CommandSequence {
112				a.cmdFreq[c]++
113			}
114			if ep.Intent != "" && len(a.intents) < 12 {
115				a.intents = append(a.intents, ep.Intent)
116			}
117			if len(a.anchors) < 3 && ep.Source.Path != "" {
118				a.anchors = append(a.anchors, ep.Source)
119			}
120		}
121	
122		var out []taskCandidate
123		for _, sig := range order {
124			a := aggs[sig]
125			if a.support < taskMinSupport || a.withCommands < taskMinWithCommands || nonTaskSignature(sig) {
126				continue
127			}
128			strength := taskStrength(a.support, a.withCommands, a.reinf)
129			out = append(out, taskCandidate{
130				ID:              taskCandidateID(a.repoKey, sig),
131				RepoKey:         a.repoKey,
132				IntentSignature: sig,
133				Label:           representativeIntent(a.intents),
134				Support:         a.support,
135				WithCommands:    a.withCommands,
136				Reinforcement:   a.reinf,
137				Commands:        topCommands(a.cmdFreq, taskTopCommands),
138				SampleIntents:   distinctSample(a.intents, taskSampleIntents),
139				Examples:        a.anchors,
140				Strength:        math.Round(strength*1000) / 1000,
141				StrengthLabel:   strengthLabel(strength),
142			})
143		}
144		sort.SliceStable(out, func(i, j int) bool {
145			if out[i].Strength != out[j].Strength {
146				return out[i].Strength > out[j].Strength
147			}
148			return out[i].ID < out[j].ID
149		})
150		return out
151	}
152	
153	func taskStrength(support, withCommands int, r reinforcementCounts) float64 {
154		recurrence := clamp01(math.Log2(1+float64(support)) / math.Log2(1+15))
155		activity := 0.0
156		if support > 0 {
157			activity = clamp01(float64(withCommands) / float64(support))
158		}
159		reinf := 0.5
160		if support > 0 {
161			reinf = clamp01(0.5 + 0.5*float64(r.Success-r.Corrected)/float64(support))
162		}
163		return 0.45*recurrence + 0.30*activity + 0.25*reinf
164	}
