166	// representativeIntent picks the longest sample intent (most descriptive),
167	// truncated — the human label for the cluster.
168	func representativeIntent(intents []string) string {
169		best := ""
170		for _, s := range intents {
171			if len(s) > len(best) {
172				best = s
173			}
174		}
175		return truncateString(best, 160)
176	}
