193			}
194			if overlap > 0 {
195				matched = append(matched, scored{v, overlap})
196			}
197		}
198		sort.SliceStable(matched, func(i, j int) bool {
199			if matched[i].overlap != matched[j].overlap {
200				return matched[i].overlap > matched[j].overlap
201			}
202			return matched[i].v.Strength > matched[j].v.Strength
203		})
204		out := make([]patternView, 0, limit)
205		for _, m := range matched {
206			if len(out) >= limit {
207				break
208			}
209			out = append(out, m.v)
210		}
211		return out
212	}
