15	// Procedure detection (Pattern Consolidation, Phase 2).
16	//
17	// A procedure is a recurring operational shape: a contiguous command n-gram
18	// (length 2-3, consecutive duplicates collapsed) that recurs across multiple
19	// episodes. n-grams (not lone commands) are the unit on purpose — a single
20	// ubiquitous command ("sed", "cd") is noise, whereas a multi-step shape
21	// ("gofmt" -> "go test" -> "git commit") is a genuine workflow.
22	//
23	// SCORING is a weighted blend in [0,1], with specificity weighted highest
24	// because suppressing ubiquitous-command noise is the core problem (per the plan
25	// review): an idf term pushes shapes built from common commands down even when
26	// they recur often. The other terms are recurrence (log-saturated episode
27	// support), reinforcement quality (success lifts, corrected sinks), and author/
28	// branch diversity. Cutoffs map the blend to high/medium/low.
29	
30	const patternsProceduresPath = "patterns/procedures.ndjson"
31	
32	const (
33		procedureMinSupport     = 3    // distinct episodes a shape needs to be a procedure
34		procedureSupportSaturat = 10   // episode count at which the recurrence term saturates
35		procedureSpecFloor      = 0.20 // drop shapes whose commands are too ubiquitous to matter
36		procedureNGramMin       = 2
37		procedureNGramMax       = 3
38	)
39	
40	// strength term weights; sum to 1.
41	const (
42		wSpecificity   = 0.40
43		wRecurrence    = 0.30
44		wReinforcement = 0.20
45		wDiversity     = 0.10
46	)
47	
48	type procedureRecord struct {
49		ID            string              `json:"id"`
50		Type          string              `json:"type"`  // always "procedure"
51		Scope         string              `json:"scope"` // "repo" | "workspace"
52		RepoKey       string              `json:"repo_key,omitempty"`
53		Workspace     string              `json:"workspace,omitempty"`
54		Commands      []string            `json:"commands"`
55		Support       int                 `json:"support"` // distinct episodes
56		Authors       int                 `json:"authors"`
57		Branches      int                 `json:"branches"`
58		Repos         int                 `json:"repos,omitempty"`          // workspace scope: repos sharing this shape
59		RepoBreakdown []patternRepoStat   `json:"repo_breakdown,omitempty"` // workspace scope
60		Reinforcement reinforcementCounts `json:"reinforcement"`
61		Strength      float64             `json:"strength"`
62		StrengthLabel string              `json:"strength_label"` // high|medium|low
63		Examples      []episodeAnchor     `json:"examples,omitempty"`
64		LastSeen      *time.Time          `json:"last_seen,omitempty"`
