74	func procedureID(scope, repoKey string, commands []string) string {
75		sum := sha256.Sum256([]byte(scope + "\x00" + repoKey + "\x00" + strings.Join(commands, "\x00")))
76		return "pattern:proc:" + hex.EncodeToString(sum[:])
77	}
