90	// buildBrainProcedures groups episodes into scored repo-local procedures. Pure
91	// over the episode set, deterministic, token-free.
92	func buildBrainProcedures(episodes []episodeRecord) []procedureRecord {
93		idf, corpus := commandIDF(episodes)
94	
95		aggs := map[string]*procedureAgg{}
96		for i := range episodes {
97			ep := &episodes[i]
98			cmds := collapseRuns(ep.CommandSequence)
99			// Distinct n-gram keys this episode contains, so a shape repeated within
100			// one episode counts that episode's support/reinforcement only once.
101			keys := map[string][]string{}
102			for n := procedureNGramMin; n <= procedureNGramMax; n++ {
103				for _, w := range commandWindows(cmds, n) {
104					keys[strings.Join(w, "\x00")] = w
105				}
106			}
107			for key, window := range keys {
108				a := aggs[key]
109				if a == nil {
110					a = &procedureAgg{
111						commands: window,
112						episodes: map[string]bool{},
113						authors:  map[string]bool{},
114						branches: map[string]bool{},
115					}
116					aggs[key] = a
117				}
118				a.episodes[ep.ID] = true
119				if ep.Author != "" {
120					a.authors[ep.Author] = true
121				}
122				if ep.Branch != "" {
123					a.branches[ep.Branch] = true
124				}
125				switch ep.Reinforcement {
126				case reinforcementSuccess:
127					a.counts.Success++
128				case reinforcementCorrected:
129					a.counts.Corrected++
130				default:
131					a.counts.Neutral++
132				}
133				if len(a.anchors) < 3 {
134					a.anchors = append(a.anchors, ep.Source)
135				}
136				if ep.CreatedAt != nil && (!a.hasSeen || ep.CreatedAt.After(a.lastSeen)) {
137					a.lastSeen = *ep.CreatedAt
138					a.hasSeen = true
139				}
140			}
141		}
142	
143		repoKey := ""
144		if len(episodes) > 0 {
145			repoKey = episodes[0].RepoKey
146		}
147	
148		var procedures []procedureRecord
149		for _, a := range aggs {
150			support := len(a.episodes)
151			if support < procedureMinSupport {
152				continue
153			}
154			spec := specificityScore(a.commands, idf, corpus)
155			if spec < procedureSpecFloor {
156				continue
157			}
158			strength := procedureStrength(spec, support, a.counts, len(a.authors), len(a.branches))
159			rec := procedureRecord{
160				ID:            procedureID("repo", repoKey, a.commands),
161				Type:          "procedure",
162				Scope:         "repo",
163				RepoKey:       repoKey,
164				Commands:      a.commands,
165				Support:       support,
166				Authors:       len(a.authors),
167				Branches:      len(a.branches),
168				Reinforcement: a.counts,
169				Strength:      math.Round(strength*1000) / 1000,
170				StrengthLabel: strengthLabel(strength),
171				Examples:      a.anchors,
172			}
173			if a.hasSeen {
174				seen := a.lastSeen
175				rec.LastSeen = &seen
176			}
177			procedures = append(procedures, rec)
178		}
179	
180		sort.Slice(procedures, func(i, j int) bool {
181			if procedures[i].Strength != procedures[j].Strength {
182				return procedures[i].Strength > procedures[j].Strength
183			}
184			if procedures[i].Support != procedures[j].Support {
185				return procedures[i].Support > procedures[j].Support
186			}
187			return procedures[i].ID < procedures[j].ID
188		})
189		return procedures
190	}
191	
192	// commandIDF returns the inverse-document-frequency weight per command (episode
193	// is the document) and the corpus size (episodes carrying >=1 command).
194	func commandIDF(episodes []episodeRecord) (map[string]float64, int) {
195		df := map[string]int{}
196		corpus := 0
197		for i := range episodes {
198			seen := map[string]bool{}
199			for _, c := range episodes[i].CommandSequence {
200				seen[c] = true
201			}
202			if len(seen) == 0 {
203				continue
204			}
205			corpus++
206			for c := range seen {
207				df[c]++
208			}
209		}
210		idf := make(map[string]float64, len(df))
211		n := float64(corpus)
212		for c, d := range df {
213			idf[c] = math.Log((1 + n) / (1 + float64(d)))
214		}
215		return idf, corpus
216	}
217	
218	// specificityScore is the average idf of the n-gram's commands normalized by the
219	// maximum possible idf, in [0,1]. Ubiquitous commands -> near 0; rare ones -> 1.
220	func specificityScore(commands []string, idf map[string]float64, corpus int) float64 {
221		if corpus == 0 || len(commands) == 0 {
222			return 0
223		}
224		maxIDF := math.Log(1 + float64(corpus))
225		if maxIDF == 0 {
226			return 0
227		}
228		sum := 0.0
229		for _, c := range commands {
230			sum += idf[c]
231		}
232		return clamp01((sum / float64(len(commands))) / maxIDF)
233	}
