20	// Skill formation (Pattern Consolidation, Phase 5).
21	//
22	// `patterns form <id>` turns a selected pattern into a reusable SKILL.md. The
23	// safety contract: nothing is written until the user confirms a destination.
24	// Without --yes the command previews (card + draft + would-write paths) and
25	// stops; --yes (which requires --name) writes; --draft-only prints only; and
26	// --decline records a decline. An existing destination file is never overwritten
27	// without --force. Every write/decline records a skill-memory decision.
28	
29	func newPatternsFormCommand(opts Options) *cobra.Command {
30		var f formOptions
31		cmd := &cobra.Command{
32			Use:   "form <pattern-id> [path]",
33			Short: "Form a pattern into a reusable skill (previews until --yes)",
34			Args:  cobra.RangeArgs(1, 2),
35			RunE: func(cmd *cobra.Command, args []string) error {
36				target := "."
37				if len(args) == 2 {
38					target = args[1]
39				} else if opts.Env.RepoRoot != "" {
40					target = opts.Env.RepoRoot
41				}
42				f.patternID = args[0]
43				return runPatternsForm(cmd.Context(), cmd, opts, target, f)
44			},
45		}
46		cmd.Flags().StringVar(&f.name, "name", "", "Skill name (required with --yes; derived for preview)")
47		cmd.Flags().StringVar(&f.target, "target", "standard", "Install target: standard|claude-code|codex|factoryai-droid|all")
48		cmd.Flags().StringVar(&f.scope, "scope", "global", "Install scope: global|repo")
49		cmd.Flags().BoolVar(&f.yes, "yes", false, "Confirm and write the skill files")
50		cmd.Flags().BoolVar(&f.force, "force", false, "Overwrite an existing skill file")
51		cmd.Flags().BoolVar(&f.draftOnly, "draft-only", false, "Print the SKILL.md draft without writing")
52		cmd.Flags().BoolVar(&f.decline, "decline", false, "Record a decline for this pattern (no file written)")
53		cmd.Flags().BoolVar(&f.asJSON, "json", false, "Emit the result as JSON")
54		return cmd
55	}
