74	func runPatternsForm(ctx context.Context, cmd *cobra.Command, opts Options, target string, f formOptions) error {
75		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
76		if err != nil {
77			return err
78		}
79		if !local {
80			return fmt.Errorf("patterns form requires a local repository path: %s", target)
81		}
82		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
83		if err != nil {
84			return err
85		}
86		brainDir := storage.BrainDir
87	
88		_, byID, err := loadPatternViews(brainDir)
89		if err != nil {
90			return err
91		}
92		view, ok := byID[f.patternID]
93		if !ok {
94			return fmt.Errorf("pattern not found: %s (run `entire brain patterns` to list ids)", f.patternID)
95		}
96		return formFromView(cmd, view, brainDir, repoDir, f, opts.Now().UTC())
97	}
