99	// formFromView runs the form decision flow for a resolved pattern. storeDir is
100	// where the skill-memory decision is recorded (the repo brain, or the workspace
101	// dir); repoDir backs repo-scope install destinations.
102	func formFromView(cmd *cobra.Command, view patternView, storeDir, repoDir string, f formOptions, now time.Time) error {
103		// Decline path: record the decision, write no files.
104		if f.decline {
105			if err := recordSkillDecision(storeDir, skillMemoryRecord{
106				PatternID: view.ID, Scope: view.Scope, Status: skillStatusDeclined,
107				Fingerprint: patternEvidenceFingerprint(view), CreatedAt: now, UpdatedAt: now,
108			}); err != nil {
109				return err
110			}
111			if f.asJSON {
112				return writeJSON(cmd, map[string]any{"pattern_id": view.ID, "status": "declined"})
113			}
114			fmt.Fprintf(cmd.OutOrStdout(), "declined: %s\n", view.ID)
115			return nil
116		}
117	
118		name := f.name
119		if name == "" {
120			name = deriveSkillName(view)
121		}
122		draft := renderSkillDraft(view, name, now)
123	
124		if f.draftOnly {
125			if f.asJSON {
126				return writeJSON(cmd, map[string]any{"pattern_id": view.ID, "name": name, "draft": draft})
127			}
128			fmt.Fprintln(cmd.OutOrStdout(), draft)
129			return nil
130		}
131	
132		destinations, err := skillDestinations(f.target, f.scope, name, repoDir)
133		if err != nil {
134			return err
135		}
136	
137		// Preview: render card + draft + would-write paths, then stop. No write.
138		if !f.yes {
139			out := cmd.OutOrStdout()
140			if f.asJSON {
141				return writeJSON(cmd, map[string]any{"pattern_id": view.ID, "name": name, "draft": draft, "would_write": destinations})
142			}
143			renderSkillCard(out, view)
144			fmt.Fprintln(out, "\n--- proposed SKILL.md ---")
145			fmt.Fprintln(out, draft)
146			fmt.Fprintln(out, "would write to:")
147			for _, d := range destinations {
148				fmt.Fprintf(out, "  %s   (%s)\n", d.Path, strings.Join(d.Agents, ", "))
149			}
150			fmt.Fprintf(out, "\nre-run with --name <name> --yes to write%s\n", overwriteHint(destinations))
151			return nil
152		}
153	
154		// Write path.
155		if f.name == "" {
156			return fmt.Errorf("--name is required with --yes")
157		}
158		if !f.force {
159			for _, d := range destinations {
160				if _, err := os.Stat(skillFilePath(d.Path)); err == nil {
161					return fmt.Errorf("refusing to overwrite existing skill file: %s (use --force)", d.Path)
162				}
163			}
164		}
165		data := []byte(draft)
166		sha := "sha256:" + hex.EncodeToString(sha256Sum(data))
167		var installs []skillInstall
168		for _, d := range destinations {
169			abs := skillFilePath(d.Path)
170			if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
171				return fmt.Errorf("create skill dir: %w", err)
172			}
173			if err := os.WriteFile(abs, data, 0o644); err != nil {
174				return fmt.Errorf("write skill: %w", err)
175			}
176			installs = append(installs, skillInstall{Agents: d.Agents, Path: d.Path, ContentSHA: sha})
177		}
178	
179		rec := skillMemoryRecord{
180			PatternID: view.ID, Scope: view.Scope, Status: skillStatusActive,
181			SkillName: name, Installs: installs, Fingerprint: patternEvidenceFingerprint(view),
182			Support: view.Support, CreatedAt: now, UpdatedAt: now,
183		}
184		if view.Reinforcement != nil {
185			rec.Reinforcement = *view.Reinforcement
186		}
187		if err := recordSkillDecision(storeDir, rec); err != nil {
188			return err
189		}
190	
191		if f.asJSON {
192			return writeJSON(cmd, map[string]any{"pattern_id": view.ID, "name": name, "status": "active", "installs": installs})
193		}
194		fmt.Fprintf(cmd.OutOrStdout(), "formed skill %q from %s:\n", name, view.ID)
195		for _, in := range installs {
196			fmt.Fprintf(cmd.OutOrStdout(), "  wrote %s   (%s)\n", in.Path, strings.Join(in.Agents, ", "))
197		}
198		return nil
199	}
200	
201	// recordSkillDecision upserts a skill-memory record by pattern id, preserving the
202	// rest of the user-state file.
203	func recordSkillDecision(brainDir string, rec skillMemoryRecord) error {
204		existing, err := loadBrainSkillMemory(brainDir)
205		if err != nil {
206			return err
207		}
208		out := make([]skillMemoryRecord, 0, len(existing)+1)
209		replaced := false
210		for _, r := range existing {
211			if r.PatternID == rec.PatternID {
212				if !r.CreatedAt.IsZero() {
213					rec.CreatedAt = r.CreatedAt // preserve original creation time on update
214				}
215				out = append(out, rec)
216				replaced = true
217				continue
218			}
219			out = append(out, r)
220		}
221		if !replaced {
222			out = append(out, rec)
223		}
224		sort.Slice(out, func(i, j int) bool { return out[i].PatternID < out[j].PatternID })
225		return writeBrainSkillMemory(brainDir, out)
226	}
227	
228	// skillDestinations resolves the install paths for a target+scope. "standard" is
229	// the cross-agent .agents/skills path (read by copilot-cli, cursor, gemini, pi);
230	// the holdouts get their own roots. "all" writes the minimal covering set.
231	func skillDestinations(target, scope, name, repoDir string) ([]skillDestination, error) {
232		standardAgents := []string{"copilot-cli", "cursor", "gemini", "pi"}
233		// Destination paths are kept slash-style for stable, cross-platform display
234		// and JSON; they are converted to an OS path only at the write boundary
235		// (skillFilePath). This keeps tests and output identical on Windows.
236		rel := path.Join("skills", name, "SKILL.md")
237	
238		mk := func(globalRoot, repoSub string, agents []string) (skillDestination, error) {
239			var base string
240			switch scope {
241			case "global":
242				base = globalRoot
243			case "repo":
244				if repoDir == "" {
245					return skillDestination{}, fmt.Errorf("repo scope requires a local repository")
246				}
247				base = filepath.ToSlash(filepath.Join(repoDir, repoSub))
248			default:
249				return skillDestination{}, fmt.Errorf("invalid scope %q (want global|repo)", scope)
250			}
251			return skillDestination{Agents: agents, Path: path.Join(base, rel)}, nil
252		}
253	
254		codexGlobal := filepath.ToSlash(os.Getenv("CODEX_HOME"))
255		if codexGlobal == "" {
256			codexGlobal = "~/.codex"
257		}
258		specs := map[string]struct {
259			globalRoot, repoSub string
260			agents              []string
261		}{
262			"standard":        {"~/.agents", ".agents", standardAgents},
263			"claude-code":     {"~/.claude", ".claude", []string{"claude-code", "opencode"}},
264			"codex":           {codexGlobal, ".codex", []string{"codex"}},
265			"factoryai-droid": {"~/.factory", ".factory", []string{"factoryai-droid"}},
266		}
267	
268		var order []string
269		switch target {
270		case "all":
271			order = []string{"standard", "claude-code", "codex", "factoryai-droid"}
272		case "standard", "claude-code", "codex", "factoryai-droid":
273			order = []string{target}
274		default:
275			return nil, fmt.Errorf("invalid target %q (want standard|claude-code|codex|factoryai-droid|all)", target)
276		}
277	
278		var dests []skillDestination
279		for _, key := range order {
280			s := specs[key]
281			d, err := mk(s.globalRoot, s.repoSub, s.agents)
282			if err != nil {
283				return nil, err
284			}
285			dests = append(dests, d)
286		}
287		return dests, nil
288	}
289	
290	func overwriteHint(dests []skillDestination) string {
291		for _, d := range dests {
292			if _, err := os.Stat(skillFilePath(d.Path)); err == nil {
293				return " (add --force to overwrite existing files)"
294			}
295		}
296		return ""
297	}
298	
299	// skillFilePath turns a slash-style destination path into an OS filesystem path,
300	// expanding a leading ~ first. Display/JSON keep the slash form; only writes use
301	// this.
302	func skillFilePath(p string) string {
303		return filepath.FromSlash(expandHomePath(p))
304	}
305	
306	var skillNameSanitize = regexp.MustCompile(`[^a-z0-9]+`)
307	
308	func deriveSkillName(v patternView) string {
309		base := v.Title
310		if v.Type == "procedure" {
311			base = strings.ReplaceAll(v.Title, " → ", " ")
312		}
313		slug := strings.Trim(skillNameSanitize.ReplaceAllString(strings.ToLower(base), "-"), "-")
314		if slug == "" {
315			slug = "skill"
316		}
317		// Keep names short and stable.
318		parts := strings.Split(slug, "-")
319		if len(parts) > 6 {
320			parts = parts[:6]
321		}
322		prefix := "do"
323		if v.Type == "practice" {
324			prefix = v.Kind
325			if prefix == "" {
326				prefix = "practice"
327			}
328		}
329		return strings.Trim(prefix+"-"+strings.Join(parts, "-"), "-")
330	}
331	
332	// renderSkillCard prints the full approval card for a pattern (richer than the
333	// listing card).
334	func renderSkillCard(out io.Writer, v patternView) {
335		label := v.Type
336		if v.Kind != "" {
337			label += "/" + v.Kind
338		}
339		fmt.Fprintf(out, "Pattern: %s\n", v.ID)
340		fmt.Fprintf(out, "Type: %s    Scope: %s    Strength: %s (%.2f)\n", label, v.Scope, v.StrengthLabel, v.Strength)
341		if v.Reinforcement != nil {
342			r := v.Reinforcement
343			fmt.Fprintf(out, "Reinforcement: %d success, %d corrected, %d neutral\n", r.Success, r.Corrected, r.Neutral)
344		}
345		fmt.Fprintf(out, "Seen in: %d\n", v.Support)
346		fmt.Fprintf(out, "\nWhat repeats:\n  %s\n", v.Title)
347		if v.Example != nil {
348			fmt.Fprintf(out, "\nEvidence:\n  %s:%d\n", v.Example.Path, v.Example.Line)
349		}
350	}
351	
352	func renderSkillDraft(v patternView, name string, now time.Time) string {
353		var b strings.Builder
354		desc := skillDescription(v)
355		fmt.Fprintf(&b, "---\nname: %s\ndescription: %s\n---\n\n", name, desc)
356		title := name
357		fmt.Fprintf(&b, "# %s\n\n", title)
358	
359		fmt.Fprintf(&b, "## Steps\n\n")
360		if v.Type == "procedure" {
361			for i, step := range strings.Split(v.Title, " → ") {
362				fmt.Fprintf(&b, "%d. `%s`\n", i+1, step)
363			}
364		} else {
365			fmt.Fprintf(&b, "%s\n", v.Title)
366		}
367	
368		fmt.Fprintf(&b, "\n## Verification\n\n")
369		if v.Type == "procedure" && strings.Contains(v.Title, "test") {
370			fmt.Fprintf(&b, "Confirm the test step passes before treating the work as done.\n")
371		} else {
372			fmt.Fprintf(&b, "Confirm the change matches the user's stated intent before moving on.\n")
373		}
374	
375		fmt.Fprintf(&b, "\n## Failure Modes\n\n")
376		if v.Reinforcement != nil && v.Reinforcement.Corrected > 0 {
377			fmt.Fprintf(&b, "This workflow was corrected in %d episode(s); double-check the result rather than assuming success.\n", v.Reinforcement.Corrected)
378		} else {
379			fmt.Fprintf(&b, "No correction signal recorded; still verify before relying on the outcome.\n")
380		}
381	
382		fmt.Fprintf(&b, "\n## Evidence\n\n")
383		fmt.Fprintf(&b, "Formed by Entire Brain from %d observation(s) with retained source anchors.\n", v.Support)
384		if v.Example != nil {
385			fmt.Fprintf(&b, "- %s:%d\n", v.Example.Path, v.Example.Line)
386		}
387		return strings.TrimRight(b.String(), "\n")
388	}
389	
390	func skillDescription(v patternView) string {
391		if v.Type == "procedure" {
392			first := v.Title
393			if i := strings.Index(v.Title, " → "); i > 0 {
394				first = v.Title[:i]
395			}
396			return fmt.Sprintf("Use when you reach for the `%s` workflow.", first)
397		}
398		kind := v.Kind
399		if kind == "" {
400			kind = "practice"
401		}
402		return fmt.Sprintf("Use as a %s when working in this repository.", kind)
403	}
404	
405	func sha256Sum(data []byte) []byte {
406		sum := sha256.Sum256(data)
407		return sum[:]
408	}
