		if s.asJSON {
			return writeJSON(cmd, map[string]any{"task_id": cand.ID, "is_skill": true, "name": name, "skill": res.SkillText})
		}
		out := cmd.OutOrStdout()
		fmt.Fprintln(out, res.SkillText)
