394	func pruneCorpusSessions(db *sql.DB, present map[string]bool) error {
395		rows, err := db.Query(`SELECT id, repo_key, session_id FROM indexed_sessions`)
396		if err != nil {
397			return err
398		}
399		type stale struct{ id, repoKey, sessionID string }
400		var drop []stale
401		for rows.Next() {
402			var s stale
403			if err := rows.Scan(&s.id, &s.repoKey, &s.sessionID); err != nil {
404				rows.Close()
405				return err
406			}
407			if !present[s.id] {
408				drop = append(drop, s)
409			}
410		}
411		rows.Close()
412		for _, s := range drop {
413			if _, err := db.Exec(`DELETE FROM episodes WHERE repo_key = ? AND session_id = ?`, s.repoKey, s.sessionID); err != nil {
414				return err
415			}
416			if _, err := db.Exec(`DELETE FROM indexed_sessions WHERE id = ?`, s.id); err != nil {
417				return err
418			}
419		}
