33		reExitCode  = regexp.MustCompile(`(?i)(?:exited with code|exit code:?)\s*(\d+)`)
34		rePatchFile = regexp.MustCompile(`(?m)^\*\*\* (Add|Update|Delete) File: (.+)$`)
35	)
36	
37	// claudeFileTools maps Claude/pi file tool names to a file action.
38	var claudeFileTools = map[string]string{
39		"read": "read", "view": "read", "cat": "read",
40		"write": "write", "create": "write",
41		"edit": "edit", "str_replace": "edit", "str_replace_editor": "edit", "apply_patch": "edit",
42	}
43	
44	// corpusEpisodeOps extracts ordered tool calls, shell commands (with exit/failure
45	// correlated by call id), and file references from one episode's work segment.
46	func corpusEpisodeOps(workText string) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
47		exitByCall := map[string]int{}
48		for i, line := range strings.Split(workText, "\n") {
49			line = strings.TrimSpace(line)
50			if !strings.HasPrefix(line, "{") {
51				continue
52			}
53			var obj map[string]any
54			if json.Unmarshal([]byte(line), &obj) != nil {
55				continue
56			}
57			ln := i + 1
58			switch jsonString(obj["type"]) {
59			case "response_item":
60				p := jsonMap(obj["payload"])
61				switch jsonString(p["type"]) {
62				case "function_call":
63					name := strings.ToLower(strings.TrimSpace(jsonString(p["name"])))
64					tools = append(tools, corpusToolOp{name: name, line: ln})
65					if cmd := shellCommandFromInput(name, p["arguments"]); cmd != "" {
66						if h := normalizeCommand(cmd); h != "" {
67							commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(p["call_id"])})
68						}
69					}
70				case "custom_tool_call":
71					name := strings.ToLower(strings.TrimSpace(jsonString(p["name"])))
72					tools = append(tools, corpusToolOp{name: name, line: ln})
73					files = append(files, patchFiles(jsonString(p["input"]), ln)...)
74				case "function_call_output", "custom_tool_call_output":
75					if id := jsonString(p["call_id"]); id != "" {
76						if code, ok := parseExitCode(jsonString(p["output"])); ok {
77							exitByCall[id] = code
78						}
79					}
80				case "patch_apply_end":
81					if id := jsonString(p["call_id"]); id != "" {
82						if code, ok := parseExitCode(jsonString(p["stdout"])); ok {
83							exitByCall[id] = code
84						}
85					}
86				}
87			case "assistant", "message":
88				msg := jsonMap(obj["message"])
89				if jsonString(obj["type"]) == "message" && jsonString(msg["role"]) != "assistant" {
90					continue
91				}
92				t, c, f := claudeContentOps(msg["content"], ln)
93				tools = append(tools, t...)
94				commands = append(commands, c...)
95				files = append(files, f...)
96			}
97		}
98		// Correlate exit codes to their commands.
99		for i := range commands {
100			if commands[i].callID == "" {
101				continue
102			}
103			if code, ok := exitByCall[commands[i].callID]; ok {
104				c := code
105				commands[i].exitCode = &c
106				commands[i].failed = code != 0
107			}
108		}
109		return tools, commands, dedupeFileRefs(files)
110	}
111	
112	func claudeContentOps(content any, ln int) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
113		blocks, ok := content.([]any)
114		if !ok {
115			return nil, nil, nil
116		}
117		for _, b := range blocks {
118			bm := jsonMap(b)
119			switch jsonString(bm["type"]) {
120			case "tool_use", "tool":
121				name := strings.ToLower(strings.TrimSpace(firstNonEmptyString(bm["name"], bm["tool"])))
122				if name == "" {
123					continue
124				}
125				tools = append(tools, corpusToolOp{name: name, line: ln})
126				if cmd := shellCommandFromInput(name, bm["input"]); cmd != "" {
127					if h := normalizeCommand(cmd); h != "" {
128						commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(bm["id"])})
129					}
130				}
131				if action, isFile := claudeFileTools[name]; isFile {
132					if p := filePathFromInput(bm["input"]); p != "" {
133						files = append(files, corpusFileRef{path: p, action: action, line: ln})
134					}
135				}
136			}
137		}
138		return tools, commands, files
139	}
140	
141	func patchFiles(patch string, ln int) []corpusFileRef {
142		var out []corpusFileRef
143		for _, m := range rePatchFile.FindAllStringSubmatch(patch, -1) {
144			action := map[string]string{"Add": "add", "Update": "edit", "Delete": "delete"}[m[1]]
145			out = append(out, corpusFileRef{path: strings.TrimSpace(m[2]), action: action, line: ln})
146		}
147		return out
148	}
149	
150	func filePathFromInput(raw any) string {
151		m := asObject(raw)
152		if m == nil {
153			return ""
154		}
155		return strings.TrimSpace(firstNonEmptyString(m["file_path"], m["path"], m["filename"]))
156	}
157	
158	func parseExitCode(output string) (int, bool) {
159		m := reExitCode.FindStringSubmatch(output)
160		if m == nil {
161			return 0, false
162		}
163		n := 0
164		for _, c := range m[1] {
165			n = n*10 + int(c-'0')
166		}
167		return n, true
168	}
169	
170	func dedupeFileRefs(in []corpusFileRef) []corpusFileRef {
171		seen := map[string]bool{}
172		var out []corpusFileRef
173		for _, f := range in {
174			if f.path == "" {
175				continue
176			}
177			key := f.path + "\x00" + f.action
178			if seen[key] {
179				continue
180			}
181			seen[key] = true
182			out = append(out, f)
183		}
184		return out
185	}
186	
187	// --- way-of-working meta hits ---
188	
189	type corpusMetaHit struct {
190		metaID string
191		quote  string
192		line   int
193	}
194	
195	// metaCueSet maps a meta_id to high-precision intent cues.
196	var metaCueSet = []struct {
197		id   string
198		cues []string
199	}{
200		{"review_request", []string{"review the", "review this", "code review", "review the changes", "review the codebase"}},
201		{"handoff_resume", []string{"continue", "resume", "pick up", "keep going", "carry on", "wrap up"}},
202		{"user_preference", []string{"i prefer", "always ", "never ", "please use", "from now on", "going forward"}},
203		{"no_egress_constraint", []string{"no egress", "no-egress", "offline", "local only", "local-only", "do not send", "without network"}},
204		{"correction_followup", correctionCues},
205	}
206	
207	var readOnlyCues = []string{"how does", "why does", "what happens", "investigate", "understand how", "explain", "where is", "what is", "did you", "analyze"}
208	
209	// classifyMetaHits returns deterministic way-of-working hits for an episode from
210	// its intent, the work segment, and whether it ran commands.
211	func classifyMetaHits(intent, workText string, nCmds int, validationCmd bool) []corpusMetaHit {
