20	// practice (way-of-working + facts), risk (corrected/failed work). Workspace and
21	// theme families are deferred to later slices. Stored in patterns +
22	// pattern_evidence; rebuilt from the corpus on every refresh.
23	
24	const (
25		candidateMinSupport = 3
26		promotionThreshold  = 0.65
27		// A task only promotes if its command shape is itself non-generic. This is
28		// what keeps generic git/review loops out of the promotable set even when an
29		// episode incidentally touched a file we hold a fact about — that knowledge
30		// belongs in a practice/risk, not a "commit" task.
31		promotionSpecFloor = 0.35
32	)
33	
34	// buildPatternCandidates rebuilds the patterns/pattern_evidence tables from the
35	// freshly-indexed corpus. Deterministic; runs inside the corpus build.
36	func buildPatternCandidates(db *sql.DB, repoKey string, now time.Time) error {
37		if _, err := db.Exec(`DELETE FROM patterns`); err != nil { // cascades pattern_evidence
38			return err
39		}
40		corpusN := corpusScalar(db, `SELECT COUNT(*) FROM episodes WHERE n_cmds > 0`)
41		if corpusN == 0 {
42			return nil
43		}
44		gramDF := loadGramDF(db)
45		ts := now.UTC().Format(time.RFC3339)
46	
47		for _, fam := range []func(*sql.DB, string, map[string]int, int, string) error{
48			insertTaskCandidates,
49			insertProcedureCandidates,
50			insertRiskCandidates,
51			insertPracticeCandidates,
52		} {
53			if err := fam(db, repoKey, gramDF, corpusN, ts); err != nil {
54				return err
55			}
56		}
57		return nil
58	}
