60	func insertTaskCandidates(db *sql.DB, repoKey string, gramDF map[string]int, corpusN int, ts string) error {
61		rows, err := db.Query(`
62			SELECT e.intent_sig, g.gram,
63			       COUNT(DISTINCT e.id),
64			       COUNT(DISTINCT e.repo_key), COUNT(DISTINCT e.author_name), COUNT(DISTINCT e.branch),
65			       SUM(e.outcome='success'), SUM(e.outcome='corrected'), SUM(e.outcome='failed'),
66			       MAX(e.created_at),
67			       MAX(CASE WHEN EXISTS(SELECT 1 FROM episode_facts ef WHERE ef.episode_id=e.id AND ef.weight >= 2) THEN 1 ELSE 0 END),
68			       MAX(CASE WHEN EXISTS(SELECT 1 FROM meta_hits mh WHERE mh.episode_id=e.id AND mh.meta_id='validation_loop') THEN 1 ELSE 0 END),
69			       MAX(CASE WHEN e.exit_fails>0 THEN 1 ELSE 0 END)
70			FROM episodes e JOIN grams g ON g.episode_id = e.id
71			WHERE e.intent_sig != '' AND e.n_cmds > 0
72			GROUP BY e.intent_sig, g.gram
73			HAVING COUNT(DISTINCT e.id) >= ?`, candidateMinSupport)
74		if err != nil {
75			return err
76		}
77		defer rows.Close()
78		for rows.Next() {
79			var (
80				intentSig, gram, lastSeen                          string
81				support, repos, authors, branches                  int
82				succ, corr, fail, hasFact, hasValid, hasFail       int
83			)
84			if err := rows.Scan(&intentSig, &gram, &support, &repos, &authors, &branches, &succ, &corr, &fail, &lastSeen, &hasFact, &hasValid, &hasFail); err != nil {
85				return err
86			}
87			spec := gramSpecificity(gram, gramDF, corpusN)
88			corroborated := hasFact == 1 || hasValid == 1 || hasFail == 1
89			score := taskScoreV2(support, spec, succ, corr, fail, repos, authors, branches, lastSeen)
90			// Promote only a specific, corroborated task — generic command shapes stay
91			// diagnostic regardless of incidental fact links.
92			score = applyPromotionGate(score, corroborated && spec >= promotionSpecFloor)
93			cluster := "task:" + intentSig + "\x00gram:" + gram
94			title := intentSig + " — " + gram
95			if err := insertPattern(db, "task", repoKey, cluster, title, intentSig, gram, score, support, repos, authors, branches, succ, corr, fail, ts); err != nil {
96				return err
97			}
98		}
99		return rows.Err()
100	}
101	
102	func insertProcedureCandidates(db *sql.DB, repoKey string, gramDF map[string]int, corpusN int, ts string) error {
103		rows, err := db.Query(`
104			SELECT g.gram, COUNT(DISTINCT g.episode_id),
105			       COUNT(DISTINCT e.repo_key), COUNT(DISTINCT e.author_name), COUNT(DISTINCT e.branch),
106			       SUM(e.outcome='success'), SUM(e.outcome='corrected'), SUM(e.outcome='failed'), MAX(e.created_at),
107			       MAX(CASE WHEN EXISTS(SELECT 1 FROM episode_facts ef WHERE ef.episode_id=e.id) THEN 1 ELSE 0 END)
108			FROM grams g JOIN episodes e ON e.id = g.episode_id
109			GROUP BY g.gram
110			HAVING COUNT(DISTINCT g.episode_id) >= ?`, candidateMinSupport)
111		if err != nil {
112			return err
113		}
114		defer rows.Close()
115		for rows.Next() {
116			var (
117				gram, lastSeen                    string
118				support, repos, authors, branches int
119				succ, corr, fail, hasFact         int
120			)
121			if err := rows.Scan(&gram, &support, &repos, &authors, &branches, &succ, &corr, &fail, &lastSeen, &hasFact); err != nil {
122				return err
123			}
124			spec := gramSpecificity(gram, gramDF, corpusN)
125			score := procedureScoreV2(support, spec, succ, corr, fail, lastSeen)
126			// Procedures are diagnostic command shapes — never dossier-eligible on
127			// their own (the plan: generic command loops stay visible but do not
128			// become high-value candidates). Promotion happens at the task/risk layer.
129			_ = hasFact
130			score = applyPromotionGate(score, false)
131			cluster := "procedure:\x00gram:" + gram
132			if err := insertPattern(db, "procedure", repoKey, cluster, gram, "", gram, score, support, repos, authors, branches, succ, corr, fail, ts); err != nil {
133				return err
134			}
135		}
136		return rows.Err()
137	}
