139	func insertRiskCandidates(db *sql.DB, repoKey string, gramDF map[string]int, corpusN int, ts string) error {
140		rows, err := db.Query(`
141			SELECT e.intent_sig, g.gram, COUNT(DISTINCT e.id),
142			       COUNT(DISTINCT e.repo_key), COUNT(DISTINCT e.author_name), COUNT(DISTINCT e.branch),
143			       SUM(e.outcome='success'), SUM(e.outcome='corrected'), SUM(e.outcome='failed'), MAX(e.created_at)
144			FROM episodes e JOIN grams g ON g.episode_id = e.id
145			WHERE e.outcome IN ('corrected','failed') AND e.intent_sig != ''
146			GROUP BY e.intent_sig, g.gram
147			HAVING COUNT(DISTINCT e.id) >= 2`)
148		if err != nil {
149			return err
150		}
151		defer rows.Close()
152		for rows.Next() {
153			var (
154				intentSig, gram, lastSeen         string
155				support, repos, authors, branches int
156				succ, corr, fail                  int
157			)
158			if err := rows.Scan(&intentSig, &gram, &support, &repos, &authors, &branches, &succ, &corr, &fail, &lastSeen); err != nil {
159				return err
160			}
161			spec := gramSpecificity(gram, gramDF, corpusN)
162			score := riskScoreV2(support, spec, corr, fail, lastSeen)
163			// Risk is its own corroboration (it IS recorded failure/correction).
164			cluster := "risk:" + intentSig + "\x00gram:" + gram
165			if err := insertPattern(db, "risk", repoKey, cluster, "risk: "+intentSig+" — "+gram, intentSig, gram, score, support, repos, authors, branches, succ, corr, fail, ts); err != nil {
166				return err
167			}
168		}
169		return rows.Err()
