171	
172	func insertPracticeCandidates(db *sql.DB, repoKey string, _ map[string]int, _ int, ts string) error {
173		rows, err := db.Query(`
174			SELECT mh.meta_id, COUNT(DISTINCT mh.episode_id),
175			       COUNT(DISTINCT e.repo_key), COUNT(DISTINCT e.author_name), COUNT(DISTINCT e.branch),
176			       SUM(e.outcome='success'), SUM(e.outcome='corrected'), SUM(e.outcome='failed'), MAX(e.created_at),
177			       MAX(CASE WHEN EXISTS(SELECT 1 FROM episode_facts ef WHERE ef.episode_id=e.id AND ef.weight >= 2) THEN 1 ELSE 0 END)
178			FROM meta_hits mh JOIN episodes e ON e.id = mh.episode_id
179			GROUP BY mh.meta_id
180			HAVING COUNT(DISTINCT mh.episode_id) >= 2`)
181		if err != nil {
182			return err
183		}
184		defer rows.Close()
185		for rows.Next() {
186			var (
187				metaID, lastSeen                  string
188				support, repos, authors, branches int
189				succ, corr, fail, hasFact         int
190			)
191			if err := rows.Scan(&metaID, &support, &repos, &authors, &branches, &succ, &corr, &fail, &lastSeen, &hasFact); err != nil {
192				return err
193			}
194			score := practiceScoreV2(support, succ, corr, repos, authors, branches, lastSeen)
195			score = applyPromotionGate(score, hasFact == 1) // a way-of-working needs fact backing to promote
196			cluster := "practice:" + metaID
197			if err := insertPatternMeta(db, "practice", repoKey, cluster, "practice: "+metaID, metaID, score, support, repos, authors, branches, succ, corr, fail, ts); err != nil {
198				return err
199			}
200		}
201		return rows.Err()
202	}
203	
204	// --- scoring (per docs/pattern_v2.md) ---
205	
206	func supportScoreV2(support int) float64 {
207		return clamp01(math.Log2(1+float64(support)) / math.Log2(31))
208	}
209	func recencyScoreV2(lastSeen string) float64 {
210		t, err := time.Parse(time.RFC3339, lastSeen)
211		if err != nil {
212			return 0.5
213		}
214		days := time.Since(t).Hours() / 24
215		switch {
216		case days <= 30:
217			return 1.0
218		case days <= 90:
219			return 0.6
220		default:
221			return 0.3
222		}
223	}
224	func outcomeScoreV2(support, succ, corr, fail int) float64 {
225		if support == 0 {
226			return 0.5
227		}
228		return clamp01(0.5 + 0.5*float64(succ-corr-fail)/float64(support))
229	}
230	func diversityScoreV2(repos, authors, branches int) float64 {
231		d := func(n int) float64 { return clamp01(float64(n-1) / 2.0) }
232		return (d(repos) + d(authors) + d(branches)) / 3.0
233	}
234	func gramSpecificity(gram string, gramDF map[string]int, corpusN int) float64 {
235		if corpusN == 0 {
236			return 0
237		}
238		df := gramDF[gram]
239		if df == 0 {
240			df = 1
241		}
242		maxIDF := math.Log(float64(corpusN))
243		if maxIDF == 0 {
244			return 0
245		}
246		return clamp01(math.Log(float64(corpusN)/float64(df)) / maxIDF)
247	}
248	
249	func taskScoreV2(support int, spec float64, succ, corr, fail, repos, authors, branches int, lastSeen string) float64 {
250		return 0.35*supportScoreV2(support) + 0.10*recencyScoreV2(lastSeen) +
251			0.25*spec + 0.20*outcomeScoreV2(support, succ, corr, fail) + 0.10*diversityScoreV2(repos, authors, branches)
252	}
253	func procedureScoreV2(support int, spec float64, succ, corr, fail int, lastSeen string) float64 {
254		return 0.30*supportScoreV2(support) + 0.10*recencyScoreV2(lastSeen) + 0.25*spec + 0.20*outcomeScoreV2(support, succ, corr, fail) + 0.15*0
255	}
256	func riskScoreV2(support int, spec float64, corr, fail int, lastSeen string) float64 {
257		rate := 1.0 // these episodes are by definition corrected/failed
258		if support == 0 {
259			rate = 0
260		}
261		_ = corr
262		_ = fail
263		return 0.30*supportScoreV2(support) + 0.30*rate + 0.20*spec + 0.20*recencyScoreV2(lastSeen)
264	}
265	func practiceScoreV2(support, succ, corr, repos, authors, branches int, lastSeen string) float64 {
266		return 0.30*supportScoreV2(support) + 0.20*outcomeScoreV2(support, succ, corr, 0) + 0.15*diversityScoreV2(repos, authors, branches) + 0.10*recencyScoreV2(lastSeen) + 0.25*0.5
267	}
268	
269	func applyPromotionGate(score float64, corroborated bool) float64 {
270		if !corroborated && score >= promotionThreshold {
271			return promotionThreshold - 0.01 // visible, but not dossier-eligible without corroboration
272		}
273		return score
274	}
275	
276	func strengthLabelV2(score float64) string {
277		switch {
278		case score >= 0.70:
279			return "high"
280		case score >= 0.50:
281			return "medium"
282		default:
283			return "low"
284		}
285	}
286	
287	// --- insertion + evidence ---
288	
289	func insertPattern(db *sql.DB, typ, repoKey, cluster, title, intentSig, gram string, score float64, support, repos, authors, branches, succ, corr, fail int, ts string) error {
290		return insertPatternRow(db, typ, repoKey, cluster, title, intentSig, gram, "", score, support, repos, authors, branches, succ, corr, fail, ts)
291	}
292	func insertPatternMeta(db *sql.DB, typ, repoKey, cluster, title, metaID string, score float64, support, repos, authors, branches, succ, corr, fail int, ts string) error {
293		return insertPatternRow(db, typ, repoKey, cluster, title, "", "", metaID, score, support, repos, authors, branches, succ, corr, fail, ts)
294	}
295	
296	func insertPatternRow(db *sql.DB, typ, repoKey, cluster, title, intentSig, gram, metaID string, score float64, support, repos, authors, branches, succ, corr, fail int, ts string) error {
297		id := "pattern:" + hexSHA(typ+"\x00repo\x00"+repoKey+"\x00\x00"+cluster)
298		score = math.Round(score*1000) / 1000
299		if _, err := db.Exec(`INSERT INTO patterns
300			(id, type, scope, repo_key, workspace, cluster_key, title, intent_sig, gram, meta_id, strength, strength_label, support,
301			 n_repos, n_authors, n_branches, outcome_success, outcome_corrected, outcome_neutral, outcome_failed, fingerprint, status, created_at, updated_at)
302			VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
303			id, typ, "repo", repoKey, "", cluster, redactText(title), intentSig, gram, metaID, score, strengthLabelV2(score), support,
304			repos, authors, branches, succ, corr, 0, fail, hexSHA(cluster+strconv.Itoa(support)), "active", ts, ts,
305		); err != nil {
306			return err
307		}
308		return insertPatternEvidence(db, id, typ, intentSig, gram, metaID)
309	}
310	
311	// insertPatternEvidence links the top supporting episodes (corrected/failed
312	// first, then successful, then recent) with their source spans.
313	func insertPatternEvidence(db *sql.DB, patternID, typ, intentSig, gram, metaID string) error {
314		var (
315			q    string
316			args []any
317		)
318		switch typ {
319		case "task", "risk":
320			q = `SELECT e.id, e.outcome, e.source_path, e.start_line, e.end_line FROM episodes e
321			     JOIN grams g ON g.episode_id=e.id WHERE e.intent_sig=? AND g.gram=?`
322			args = []any{intentSig, gram}
323		case "procedure":
324			q = `SELECT e.id, e.outcome, e.source_path, e.start_line, e.end_line FROM episodes e
325			     JOIN grams g ON g.episode_id=e.id WHERE g.gram=?`
326			args = []any{gram}
327		case "practice":
328			q = `SELECT e.id, e.outcome, e.source_path, e.start_line, e.end_line FROM episodes e
329			     JOIN meta_hits mh ON mh.episode_id=e.id WHERE mh.meta_id=?`
330			args = []any{metaID}
331		default:
332			return nil
333		}
334		q += ` ORDER BY CASE e.outcome WHEN 'corrected' THEN 0 WHEN 'failed' THEN 1 WHEN 'success' THEN 2 ELSE 3 END, e.created_at DESC LIMIT 3`
335		rows, err := db.Query(q, args...)
336		if err != nil {
337			return err
338		}
339		defer rows.Close()
340		rank := 0
341		type ev struct {
342			id, outcome, path string
343			start, end        int
344		}
345		var evs []ev
346		for rows.Next() {
347			var e ev
348			if err := rows.Scan(&e.id, &e.outcome, &e.path, &e.start, &e.end); err != nil {
349				return err
350			}
351			evs = append(evs, e)
352		}
353		rows.Close()
354		for _, e := range evs {
355			if _, err := db.Exec(`INSERT OR IGNORE INTO pattern_evidence (pattern_id, episode_id, rank, outcome, source_path, start_line, end_line) VALUES (?,?,?,?,?,?,?)`,
356				patternID, e.id, rank, e.outcome, e.path, e.start, e.end); err != nil {
357				return err
358			}
359			rank++
360		}
361		return nil
362	}
363	
364	func loadGramDF(db *sql.DB) map[string]int {
365		out := map[string]int{}
366		rows, err := db.Query(`SELECT gram, COUNT(DISTINCT episode_id) FROM grams GROUP BY gram`)
367		if err != nil {
368			return out
369		}
370		defer rows.Close()
371		for rows.Next() {
372			var g string
373			var n int
374			if rows.Scan(&g, &n) == nil {
375				out[g] = n
376			}
377		}
378		return out
379	}
380	
381	func corpusScalar(db *sql.DB, q string, args ...any) int {
382		var n int
383		if err := db.QueryRow(q, args...).Scan(&n); err != nil {
384			return 0
385		}
386		return n
387	}
