122	// loadPatternViews loads procedures + practices as unified views and an index by
123	// pattern id.
124	func loadPatternViews(brainDir string) ([]patternView, map[string]patternView, error) {
125		procedures, err := loadBrainProcedures(brainDir)
126		if err != nil {
127			return nil, nil, err
128		}
129		practices, err := loadBrainPractices(brainDir)
130		if err != nil {
131			return nil, nil, err
132		}
133		views := make([]patternView, 0, len(procedures)+len(practices))
134		for _, p := range procedures {
135			views = append(views, procedureView(p))
136		}
137		for _, p := range practices {
138			views = append(views, practiceView(p))
139		}
140		idx := make(map[string]patternView, len(views))
141		for _, v := range views {
142			idx[v.ID] = v
143		}
144		return views, idx, nil
145	}
146	
147	// strongestPatterns loads the top-N patterns by strength for the overview.
148	func strongestPatterns(brainDir string, limit int) []patternView {
149		views, _, err := loadPatternViews(brainDir)
150		if err != nil || len(views) == 0 {
151			return nil
152		}
153		sort.SliceStable(views, func(i, j int) bool { return views[i].Strength > views[j].Strength })
154		if limit > 0 && len(views) > limit {
155			views = views[:limit]
156		}
157		return views
158	}
159	
160	// brainBriefPatternsCount caps how many task-relevant patterns the brief carries.
161	func brainBriefPatternsCount(limit int) int {
162		if limit <= 0 || limit > 5 {
163			return 5
164		}
165		return limit
166	}
167	
168	// rankTaskRelevantPatterns returns the patterns whose title/kind share a term
169	// with the task, ranked by term overlap then strength. Patterns with no overlap
170	// are dropped — the brief should surface task-relevant patterns, not ambient
171	// noise — so an unrelated task yields none.
172	func rankTaskRelevantPatterns(views []patternView, terms []string, limit int) []patternView {
173		if limit <= 0 || len(terms) == 0 {
174			return nil
175		}
176		termSet := make(map[string]bool, len(terms))
177		for _, t := range terms {
178			termSet[t] = true
179		}
180		type scored struct {
181			v       patternView
182			overlap int
183		}
184		var matched []scored
185		for _, v := range views {
186			seen := map[string]bool{}
187			overlap := 0
188			for _, w := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(v.Title+" "+v.Kind), -1) {
189				if termSet[w] && !seen[w] {
190					seen[w] = true
191					overlap++
192				}
193			}
194			if overlap > 0 {
195				matched = append(matched, scored{v, overlap})
196			}
197		}
198		sort.SliceStable(matched, func(i, j int) bool {
199			if matched[i].overlap != matched[j].overlap {
200				return matched[i].overlap > matched[j].overlap
201			}
202			return matched[i].v.Strength > matched[j].v.Strength
203		})
204		out := make([]patternView, 0, limit)
205		for _, m := range matched {
206			if len(out) >= limit {
207				break
208			}
209			out = append(out, m.v)
210		}
211		return out
212	}
213	
214	// mustLoadSkillMemory returns skill-memory records, treating a read/parse error
215	// as empty — the listing should degrade to "no recommendations", not fail.
216	func mustLoadSkillMemory(brainDir string) []skillMemoryRecord {
217		records, err := loadBrainSkillMemory(brainDir)
218		if err != nil {
219			return nil
220		}
221		return records
222	}
