224	func procedureView(p procedureRecord) patternView {
225		r := p.Reinforcement
226		v := patternView{
227			ID: p.ID, Type: p.Type, Scope: p.Scope,
228			Title:    strings.Join(p.Commands, " → "),
229			Strength: p.Strength, StrengthLabel: p.StrengthLabel,
230			Support: p.Support, Reinforcement: &r,
231			Repos: p.Repos, RepoBreakdown: p.RepoBreakdown,
232		}
233		if len(p.Examples) > 0 {
234			v.Example = &p.Examples[0]
235		}
236		return v
