334		var wantFact, wantHistory, wantDoc bool
335		for _, id := range ids {
336			switch {
337			case strings.HasPrefix(id, "fact:"):
338				wantFact = true
339			case strings.HasPrefix(id, "history:"):
340				wantHistory = true
341			case strings.HasPrefix(id, "doc:"):
342				wantDoc = true
343			}
