111		// Delete the rebuildable corpus entirely (and its WAL/SHM siblings).
112		for _, suffix := range []string{"", "-wal", "-shm"} {
113			os.Remove(corpusPath + suffix)
114		}
115		if err := buildPatternCorpus(brainDir, now); err != nil {
116			t.Fatalf("corpus must regenerate after deletion: %v", err)
117		}
118		got, err := loadBrainSkillMemory(brainDir)
119		if err != nil {
120			t.Fatal(err)
121		}
122		if len(got) != 1 || got[0].PatternID != "pattern:abc" || got[0].Status != "declined" {
123			t.Errorf("user decision lost across corpus delete+rebuild: %+v", got)
124		}
125	}
